import { getBoundingBox, getSubpaths } from "@remotion/paths";
import { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Interactive, Sequence, interpolate, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Each tube of the sign stutters on in turn, then the whole sign buzzes out
// once and its glow settles. Frames on the 30 fps scene timeline, after
// `speed`. The ids are public: a saved `timing` prop refers to them.

type NeonSignElementId = `tube:${number}` | "buzz";

interface NeonSignTimingProps {
  path?: string;
  seed?: number;
}

// Handwritten "hello" with an underline swash, one subpath per tube.
const HELLO = [
  "M 30 132 C 52 112 74 70 70 46 C 67 28 50 30 47 52 C 44 76 42 112 40 140 C 46 116 58 100 72 100 C 86 100 84 122 86 134 C 88 144 100 144 110 132",
  "M 110 132 C 124 124 142 110 136 98 C 130 88 112 96 112 116 C 112 138 134 146 156 130",
  "M 156 130 C 176 110 196 66 190 46 C 186 32 170 36 168 60 C 166 90 168 126 172 136 C 176 146 188 142 196 132",
  "M 196 132 C 216 110 232 66 226 46 C 222 32 206 36 204 60 C 202 90 204 126 208 136 C 212 146 224 142 232 132",
  "M 232 132 C 238 116 248 100 262 100 C 278 100 280 124 268 136 C 256 146 242 136 248 118 C 252 106 268 104 290 104",
  "M 52 170 C 120 160 210 162 296 152",
].join(" ");
const DEFAULT_SEED = 7;

const FIRST = 3;
const STEP = 3.4;
const STUTTER = 7;
/** The sign drops out to these levels, one frame each, from `BUZZ_AT`. */
const BUZZ_LEVELS = [0.1, 0, 0.55, 0.2];
const BUZZ_AT = 29;
const SETTLE_AT = 32;
const SETTLE_END = 40;

// Remotion's `random()` for a string seed, so each tube's onset stays
// exactly as it was.
function mulberry32(a: number) {
  let t = a + 1831565813;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function seeded(seed: string) {
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash << 5) - hash + seed.charCodeAt(i);
    hash |= 0;
  }
  return mulberry32(hash);
}

/** Subpaths in an SVG path: one per `M` or `m` command. */
const tubesIn = (path: string) => (path.match(/[Mm]/g) ?? []).length;

// A tube's element is its stutter; once it ends the tube is lit. The buzz
// drops the sign to `BUZZ_LEVELS`, one `pulse` each, and the glow settles
// from `settle` to `settleEnd`.
const neonSignTimeline = defineTimeline<
  NeonSignElementId,
  NeonSignTimingProps
>(({ path = HELLO, seed = DEFAULT_SEED }) => {
  const elements: TimelineElement<NeonSignElementId>[] = Array.from(
    { length: tubesIn(path) },
    (_, i) => ({
      id: `tube:${i}` as const,
      lane: "Tubes",
      label: `Tube ${i + 1}`,
      start: FIRST + i * STEP + seeded(`neon-sign-${seed}-${i}`) * 2,
      length: STUTTER,
      follows: i > 0 ? (`tube:${i - 1}` as const) : undefined,
    }),
  );
  elements.push({
    id: "buzz",
    lane: "Buzz",
    label: "Sign buzzes",
    start: BUZZ_AT,
    length: SETTLE_END - BUZZ_AT,
    beats: {
      pulse: 1,
      settle: SETTLE_AT - BUZZ_AT,
      settleEnd: SETTLE_END - BUZZ_AT,
    },
  });
  return elements.sort((a, b) => a.start - b.start);
});

type NeonSignProps = {
  /** SVG path data for the tube. Each subpath (M command) flickers on its own. */
  path?: string;
  /** viewBox for the path. Defaults to the path's bounding box. */
  viewBox?: string;
  /** Tube color when lit. */
  color?: string;
  /** Color of the halo and the glow on the wall. */
  glowColor?: string;
  /** Unlit glass tube. */
  tubeColor?: string;
  /** Color of the hot core inside the tube. */
  coreColor?: string;
  backgroundColor?: string;
  /** Tube thickness in path units. */
  strokeWidth?: number;
  /** Share of the frame width the sign spans. */
  fit?: number;
  seed?: number;
  speed?: number;
  /**
   * Moves, trims or stretches each tube's flicker and the buzz, by the ids
   * in `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<NeonSignElementId>;
};

const neonSignDefaults = {
  path: HELLO,
  color: "#E5322D",
  glowColor: "#E5322D",
  tubeColor: "#2A2A2A",
  coreColor: "#FFFFFF",
  backgroundColor: "#111111",
  strokeWidth: 6,
  fit: 0.62,
  seed: DEFAULT_SEED,
  speed: 1,
};

const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

function segmentLevel(
  t: number,
  i: number,
  seed: number,
  tube: { start: number; end: number; length: number },
) {
  const onset = tube.start;
  if (t < onset) return 0;
  if (t < tube.end) {
    const tick = Math.floor(t);
    const v = random(`neon-sign-${seed}-${i}-${tick}`);
    const ramp = (t - onset) / tube.length;
    return v < 0.5 - ramp * 0.3 ? 0.04 : 0.55 + 0.45 * v;
  }
  return 1;
}

function NeonSignBase(props: NeonSignProps) {
  const {
    path,
    viewBox,
    color,
    glowColor,
    tubeColor,
    coreColor,
    backgroundColor,
    strokeWidth,
    fit,
    seed,
    speed,
    timing,
  } = { ...neonSignDefaults, ...props };
  const uid = `neon-sign-${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  const frame = useSceneFrame();
  const { width, height, durationInFrames } = useSceneConfig();
  const t = frame * Math.max(0, speed);
  const tl = useTimeline(
    neonSignTimeline,
    props,
    durationInFrames * Math.max(0, speed),
    timing,
  );
  const buzzEl = tl.get("buzz");

  const segments = useMemo(() => getSubpaths(path), [path]);
  const box = useMemo(() => {
    if (viewBox) {
      const [x, y, w, h] = viewBox.split(/[\s,]+/).map(Number);
      return { x, y, w, h };
    }
    const b = getBoundingBox(path);
    const pad = strokeWidth * 6;
    return {
      x: b.x1 - pad,
      y: b.y1 - pad,
      w: b.width + pad * 2,
      h: b.height + pad * 2,
    };
  }, [path, viewBox, strokeWidth]);

  const pulse = Math.floor((t - buzzEl.start) / buzzEl.beat("pulse"));
  const buzz = BUZZ_LEVELS[pulse] ?? 1;
  const levels = segments.map(
    (_, i) => segmentLevel(t, i, seed, tl.get(`tube:${i}`)) * buzz,
  );
  const average =
    levels.reduce((a, b) => a + b, 0) / Math.max(1, levels.length);

  const scale = Math.min((width * fit) / box.w, (height * 0.7) / box.h);
  const drawW = box.w * scale;
  const drawH = box.h * scale;
  const settle = interpolate(
    t,
    [
      buzzEl.start + buzzEl.beat("settle"),
      buzzEl.start + buzzEl.beat("settleEnd"),
    ],
    [0.85, 1],
    clamp,
  );

  return (
    <AbsoluteFill style={{ backgroundColor }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse ${drawW * 0.75}px ${drawH * 0.85}px at 50% 50%, ${glowColor} 0%, transparent 100%)`,
          opacity: 0.28 * average * settle,
        }}
      />
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <svg
          width={drawW}
          height={drawH}
          viewBox={`${box.x} ${box.y} ${box.w} ${box.h}`}
          style={{ overflow: "visible" }}
        >
          <defs>
            <filter
              id={`${uid}-wide`}
              filterUnits="userSpaceOnUse"
              x={box.x - box.w}
              y={box.y - box.h}
              width={box.w * 3}
              height={box.h * 3}
            >
              <feGaussianBlur stdDeviation={strokeWidth * 2.2} />
            </filter>
            <filter
              id={`${uid}-near`}
              filterUnits="userSpaceOnUse"
              x={box.x - box.w}
              y={box.y - box.h}
              width={box.w * 3}
              height={box.h * 3}
            >
              <feGaussianBlur stdDeviation={strokeWidth * 0.6} />
            </filter>
          </defs>
          <g fill="none" strokeLinecap="round" strokeLinejoin="round">
            {segments.map((d, i) => (
              <path
                key={`tube-${i}`}
                d={d}
                stroke={tubeColor}
                strokeWidth={strokeWidth}
              />
            ))}
            {segments.map((d, i) => {
              const level = levels[i];
              if (level <= 0) return null;
              return (
                <g key={`lit-${i}`}>
                  <path
                    d={d}
                    stroke={glowColor}
                    strokeWidth={strokeWidth * 3}
                    opacity={0.7 * level}
                    filter={`url(#${uid}-wide)`}
                  />
                  <path
                    d={d}
                    stroke={color}
                    strokeWidth={strokeWidth * 1.6}
                    opacity={0.9 * level}
                    filter={`url(#${uid}-near)`}
                  />
                  <path
                    d={d}
                    stroke={color}
                    strokeWidth={strokeWidth}
                    opacity={level}
                  />
                  <path
                    d={d}
                    stroke={coreColor}
                    strokeWidth={strokeWidth * 0.36}
                    opacity={0.9 * level}
                  />
                </g>
              );
            })}
          </g>
        </svg>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  strokeWidth: {
    type: "number",
    default: 6,
    min: 2,
    max: 14,
    step: 1,
    description: "Tube width",
    hiddenFromList: false,
  },
  fit: {
    type: "number",
    default: 0.62,
    min: 0.3,
    max: 0.9,
    step: 0.01,
    description: "Fit",
    hiddenFromList: false,
  },
  seed: {
    type: "number",
    default: 7,
    min: 1,
    max: 99,
    step: 1,
    description: "Seed",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#E5322D",
    description: "Tube",
  },
  glowColor: {
    type: "color",
    default: "#E5322D",
    description: "Glow",
  },
  tubeColor: {
    type: "color",
    default: "#2A2A2A",
    description: "Unlit tube",
  },
  coreColor: {
    type: "color",
    default: "#FFFFFF",
    description: "Core",
  },
  backgroundColor: {
    type: "color",
    default: "#111111",
    description: "Background",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["strokeWidth","fit","seed","color","glowColor","tubeColor","coreColor","backgroundColor","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  strokeWidth: 6,
  fit: 0.62,
  seed: 7,
  color: "#E5322D",
  glowColor: "#E5322D",
  tubeColor: "#2A2A2A",
  coreColor: "#FFFFFF",
  backgroundColor: "#111111",
  speed: 1,
};

type NeonSignElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof NeonSignBase>;

const NeonSignInner = forwardRef<
  HTMLDivElement,
  NeonSignElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<NeonSign>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <NeonSignBase
          {...(componentProps as unknown as ComponentProps<typeof NeonSignBase>)}
        />
      </div>
    </Sequence>
  );
});

export const NeonSign = Interactive.withSchema({
  Component: NeonSignInner,
  componentName: "<NeonSign>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
